    <div class="stats">${stat('inbox','c-fin','Requests received','396','▲ 11% vs previous 6 months','var(--t-mint)',1)}${stat('check','c-ok','Approved','281','71% approval rate')}${stat('clock','c-food','Avg. time to decision','4.2 days','▼ 1.3 days','var(--ok)')}${stat('globe','c-edu','Applied online','64%','Rest by phone or walk-in')}</div>
